// ─────────────────────────────────────────────
// CONTROLE DIÁRIO DE LIMITE
// Reseta o contador a meia-noite e para o fluxo
// se já atingiu 25 posts relevantes no dia.
// ─────────────────────────────────────────────
const hoje = new Date().toISOString().slice(0, 10);
const chave = `relevantes_${hoje}`;

// Lê o contador salvo no Static Data do workflow
const staticData = $getWorkflowStaticData('global');
if (!staticData[chave]) staticData[chave] = 0;

const total = staticData[chave];

if (total >= 25) {
  // Já atingiu o limite do dia — para o fluxo
  return [];
}

// Passa adiante com o contador atual
return [{ json: { relevantes_hoje: total, chave_contador: chave, pagina_cursor: null } }];

// ─────────────────────────────────────────────
// TERMOS DE BUSCA
// Adicione ou remova termos conforme necessário.
// O fluxo vai rodar uma busca para cada termo.
// ─────────────────────────────────────────────
const termos = [
  "gestor de tráfego clínica",
  "agenda vazia clínica",
  "agendamento clínica estética",
  "processo comercial clínica",
  "marketing clínica estética",
  "captação pacientes harmonização",
  "harmonização orofacial",
  "HOF botox"
];

return termos.map(termo => ({
  json: {
    termo,
    relevantes_hoje: $input.first().json.relevantes_hoje,
    chave_contador: $input.first().json.chave_contador
  }
}));

// ─────────────────────────────────────────────
// EXTRAIR POSTS DA RESPOSTA DA API
// A API do Threads retorna { data: [...], paging: {...} }
// ─────────────────────────────────────────────
const resposta = $input.first().json;
const posts = resposta.data || [];
const cursor_proximo = resposta.paging?.cursors?.after || null;
const termo = $('3. Definir termos de busca').first().json.termo;
const chave_contador = $('2. Verificar limite diário').first().json.chave_contador;
const relevantes_hoje = $('2. Verificar limite diário').first().json.relevantes_hoje;

if (posts.length === 0) return [];

return posts.map(post => ({
  json: {
    post_id: post.id,
    texto: post.text || '',
    data: post.timestamp,
    link: post.permalink,
    username: post.username || '',
    nome_perfil: post.name || '',
    bio: post.biography || '',
    termo_busca: termo,
    cursor_proximo,
    chave_contador,
    relevantes_hoje
  }
}));

