// ─────────────────────────────────────────────
// ATUALIZAR CONTADOR DIÁRIO
// Incrementa o contador de relevantes do dia
// ─────────────────────────────────────────────
const staticData = $getWorkflowStaticData('global');
const chave = $('5. Extrair posts').first().json.chave_contador;

if (!staticData[chave]) staticData[chave] = 0;
staticData[chave] += 1;

const gancho = $json.message?.content || '';
const dadosPost = $('5. Extrair posts').first().json;

return [{
  json: {
    data_coleta: new Date().toLocaleDateString('pt-BR'),
    hora_coleta: new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
    nome_perfil: dadosPost.nome_perfil,
    username: `@${dadosPost.username}`,
    bio: dadosPost.bio,
    link_post: dadosPost.link,
    texto_post: dadosPost.texto,
    gancho_prospeccao: gancho,
    termo_busca: dadosPost.termo_busca,
    relevantes_hoje: staticData[chave]
  }
}];
